#include <iostream>
#include <vector>

void printPrimesUpTo(std::size_t limit) {
    std::vector<bool> isPrime(limit + 1, true);
    if (limit >= 0) isPrime[0] = false;
    if (limit >= 1) isPrime[1] = false;

    for (std::size_t p = 2; p * p <= limit; ++p) {
        if (isPrime[p]) {
            for (std::size_t multiple = p * p; multiple <= limit; multiple += p) {
                isPrime[multiple] = false;
            }
        }
    }

    std::cout << "Primes up to " << limit << ":\n";
    std::size_t count = 0;
    for (std::size_t i = 2; i <= limit; ++i) {
        if (isPrime[i]) {
            std::cout << i << ' ';
            ++count;
        }
    }
    std::cout << "\nTotal primes: " << count << '\n';
}

int main() {
    std::size_t limit = 50;
    printPrimesUpTo(limit);
    return 0;
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>

bool testPalindrome(const std::string& s, std::size_t left, std::size_t right) {
    if (left >= right) {
        return true;
    }
    if (s[left] != s[right]) {
        return false;
    }
    return testPalindrome(s, left + 1, right - 1);
}

int recursiveMinimum(const std::vector<int>& arr, std::size_t start, std::size_t end) {
    if (start == end) {
        return arr[start];
    }
    int subMin = recursiveMinimum(arr, start + 1, end);
    return std::min(arr[start], subMin);
}

int main() {
    std::string text = "radar";
    bool isPal = testPalindrome(text, 0, text.size() - 1);
    std::cout << text << " is palindrome: " << (isPal ? "true" : "false") << '\n';

    std::vector<int> numbers = {34, 12, 89, 5, 67, 23};
    int minVal = recursiveMinimum(numbers, 0, numbers.size() - 1);
    std::cout << "Smallest element: " << minVal << '\n';
    return 0;
}

#include <iostream>
#include <array>
#include <iomanip>

constexpr int BOARD_SIZE = 5;
constexpr std::array<int, 8> dRow = {-1, -2, -2, -1,  1,  2, 2, 1};
constexpr std::array<int, 8> dCol = { 2,  1, -1, -2, -2, -1, 1, 2};

bool isValid(int r, int c, const std::array<std::array<int, BOARD_SIZE>, BOARD_SIZE>& board) {
    return (r >= 0 && r < BOARD_SIZE && c >= 0 && c < BOARD_SIZE && board[r][c] == 0);
}

int getDegree(int r, int c, const std::array<std::array<int, BOARD_SIZE>, BOARD_SIZE>& board) {
    int count = 0;
    for (int i = 0; i < 8; ++i) {
        if (isValid(r + dRow[i], c + dCol[i], board)) {
            ++count;
        }
    }
    return count;
}

int main() {
    std::array<std::array<int, BOARD_SIZE>, BOARD_SIZE> board{};
    int r = 0, c = 0;
    board[r][c] = 1;

    for (int move = 2; move <= BOARD_SIZE * BOARD_SIZE; ++move) {
        int minDegree = 9;
        int bestR = -1;
        int bestC = -1;

        for (int i = 0; i < 8; ++i) {
            int nextR = r + dRow[i];
            int nextC = c + dCol[i];
            if (isValid(nextR, nextC, board)) {
                int deg = getDegree(nextR, nextC, board);
                if (deg < minDegree) {
                    minDegree = deg;
                    bestR = nextR;
                    bestC = nextC;
                }
            }
        }

        if (bestR == -1) {
            std::cout << "Tour ended prematurely at step " << move - 1 << '\n';
            return 0;
        }
        r = bestR;
        c = bestC;
        board[r][c] = move;
    }

    std::cout << "Knight's Tour (5x5 grid starting at 0,0):\n";
    for (const auto& row : board) {
        for (int cell : row) {
            std::cout << std::setw(3) << cell << ' ';
        }
        std::cout << '\n';
    }
    return 0;
}
